// src/adapters/intelipost-tabela.ts
function buscarRota(t, cep) {
  let lo = 0, hi = t.rotas.length - 1;
  while (lo <= hi) {
    const m = lo + hi >> 1;
    const [a, b] = t.rotas[m];
    if (cep < a) hi = m - 1;
    else if (cep > b) lo = m + 1;
    else return t.rotas[m];
  }
  return void 0;
}
var minPct = (min, pct, base) => pct > 0 || min > 0 ? Math.max(min, pct / 100 * base) : 0;
function calcularIntelipost(t, p, req, ufDestino) {
  const peso = Math.max(pesoReal(req), cubagemM3(req) * t.cubagem_kg_m3);
  const nf = req.valor_nf;
  const i = t.faixas_kg.findIndex((lim) => peso <= lim);
  const fretePeso = i >= 0 ? p.faixas[i] : p.faixas[p.faixas.length - 1] + (peso - t.faixas_kg[t.faixas_kg.length - 1]) * p.excedente_kg;
  const gris = minPct(p.gris_min, p.gris_pct, nf);
  const seguro = minPct(p.seguro_min, p.seguro_pct, nf);
  const pedagio = p.pedagio > 0 ? Math.ceil(peso / (p.pedagio_fracao_kg || 100)) * p.pedagio : 0;
  const emex = minPct(p.emex_min, p.emex_pct, nf);
  const fluvial = minPct(p.fluvial_min, p.fluvial_pct, nf);
  const trt1 = minPct(p.trt1_min, p.trt1_pct, fretePeso);
  const taxas = p.tas + p.trt + p.cte + emex + fluvial + trt1;
  const subtotal = fretePeso + gris + seguro + pedagio + taxas;
  const aliq = t.icms_incluso ? 0 : aliquotaIcmsDeMG(ufDestino);
  const total = subtotal / (1 - aliq);
  return {
    peso_taxado_kg: arred(peso, 3),
    preco_total: arred(total),
    aliquota_icms: aliq,
    composicao: {
      frete_peso: arred(fretePeso),
      ad_valorem: arred(seguro),
      gris: arred(gris),
      pedagio: arred(pedagio),
      taxas: arred(taxas),
      icms: arred(total - subtotal)
    },
    detalhe: { tas: p.tas, trt: p.trt, cte: p.cte, emex: arred(emex), fluvial: arred(fluvial), trt1: arred(trt1) }
  };
}
function intelipostAdapter(t, opts = {}) {
  const id = `tabela:${t.transportadora.toLowerCase()}`;
  const base = { adaptador: id, transportadora: t.transportadora, servico: "Rodovi\xE1rio", fonte: "tabela" };
  return {
    id,
    transportadora: t.transportadora,
    fonte: "tabela",
    atende: (req) => buscarRota(t, Number(soDigitos(req.destino.cep))) ? { ok: true } : { ok: false, motivo: `CEP fora da tabela ${t.transportadora}` },
    async cotar(req) {
      const rota = buscarRota(t, Number(soDigitos(req.destino.cep)));
      if (!rota) return [{ ...base, status: "nao_atende", mensagem: "CEP fora da tabela" }];
      const uf = req.destino.uf ?? ufPorCep(req.destino.cep) ?? "SP";
      const c = calcularIntelipost(t, t.perfis[rota[3]], req, uf);
      const extras = Object.entries(c.detalhe).filter(([k, v]) => v > 0 && !["tas", "cte"].includes(k)).map(([k]) => k.toUpperCase());
      return [{
        ...base,
        status: "ok",
        preco_total: c.preco_total,
        composicao: c.composicao,
        prazo_min_du: rota[2],
        prazo_max_du: rota[2],
        peso_taxado_kg: c.peso_taxado_kg,
        volumes: qtdVolumes(req),
        mensagem: [opts.nota, `ICMS ${(c.aliquota_icms * 100).toFixed(0)}% por fora`, extras.length ? `inclui ${extras.join(", ")}` : ""].filter(Boolean).join(" \xB7 "),
        raw: { rota, calculo: c }
      }];
    }
  };
}

// src/adapters/mandae-tabela.ts
function buscarFaixa(abr, cep) {
  let lo = 0, hi = abr.length - 1;
  while (lo <= hi) {
    const mid = lo + hi >> 1;
    if (cep < abr[mid][0]) hi = mid - 1;
    else if (cep > abr[mid][1]) lo = mid + 1;
    else return abr[mid];
  }
  return void 0;
}
function pesoTaxadoMandae(req, divisor = 0) {
  if (!divisor) return pesoReal(req);
  const cubado = req.volumes.reduce((s, v) => s + v.altura_cm * v.largura_cm * v.comprimento_cm * v.quantidade / divisor, 0);
  return Math.max(pesoReal(req), cubado);
}
function precoPorPeso(area, tipo, uf, pesoKg) {
  const g = Math.ceil(pesoKg * 1e3);
  const lista = area.precos[tipo][uf];
  const i = area.faixas_g.findIndex(([a, b]) => g >= a && g <= b);
  if (i >= 0) return lista[i];
  const ultimo = area.faixas_g.length - 1;
  const excedenteKg = Math.ceil((g - area.faixas_g[ultimo][1]) / 1e3);
  return lista[ultimo] + excedenteKg * area.kg_adicional[tipo][uf];
}
function mandaeAdapter(t, opts = {}) {
  const div = opts.divisorCubagem ?? 0;
  const seguro = opts.seguroSobreNF ?? true;
  return {
    id: `tabela:mandae-${t.tabela}`,
    transportadora: "Manda\xEA",
    fonte: "tabela",
    atende(req) {
      const cep = Number(soDigitos(req.destino.cep));
      return buscarFaixa(t.servicos.economico.abrangencia, cep) ? { ok: true } : { ok: false, motivo: "CEP fora da abrang\xEAncia Manda\xEA" };
    },
    async cotar(req) {
      const cep = Number(soDigitos(req.destino.cep));
      const peso = pesoTaxadoMandae(req, div);
      return Object.entries(t.servicos).map(([chave, s]) => {
        const base = { adaptador: `tabela:mandae-${chave}`, transportadora: "Manda\xEA", servico: s.nome, fonte: "tabela" };
        const f = buscarFaixa(s.abrangencia, cep);
        if (!f) return { ...base, status: "nao_atende", mensagem: "CEP fora da abrang\xEAncia" };
        const [, , uf, tipo, area, taxaSeguro, prazo] = f;
        const frete = precoPorPeso(s.areas[area], tipo, uf, peso);
        const valorSeguro = seguro ? taxaSeguro * req.valor_nf : 0;
        return {
          ...base,
          status: "ok",
          preco_total: arred(frete + valorSeguro),
          composicao: { frete_peso: arred(frete), seguro: arred(valorSeguro) },
          prazo_min_du: prazo,
          prazo_max_du: prazo,
          peso_taxado_kg: arred(peso, 3),
          volumes: qtdVolumes(req),
          mensagem: `${area} \xB7 ${uf} ${tipo} \xB7 impostos inclusos`,
          raw: { faixa: f }
        };
      });
    }
  };
}

