      if (/destinat[aá]rio n[aã]o encontrado/i.test(j?.Message ?? "") && reqDest.destino.documento) {
        ({ j, status } = await enviar({ ...reqDest, destino: { ...reqDest.destino, documento: void 0 } }));
        obs = "destinat\xE1rio n\xE3o cadastrado na Rodonaves: cotado pelo endere\xE7o de entrega";
      }
      const o = paraOpcao2(j, status, base, req);
      if (obs && o.status === "ok") o.mensagem = [o.mensagem, obs].filter(Boolean).join(" \xB7 ");
