// src/adapters/tabela-fracionada.ts
var COL_FAIXA = ["ate10", "ate20", "ate30", "ate50", "ate70", "ate100"];
function escolherRota(t, uf, cidade) {
  const capital = ehCapital(uf, cidade);
  const daUf = t.rotas.filter((r) => r.uf === uf);
  if (!daUf.length) return {};
  if (capital) {
    const r = daUf.find((x) => x.tipo === "capital" && x.regiao !== "polo") ?? daUf.find((x) => x.tipo === "capital");
    return { rota: r, alerta: uf === "RJ" ? "RJ capital: usei 'Rio Regi\xE3o'; 'Rio Polo' tem EMEX e ad valorem maior." : void 0 };
  }
  const interior = daUf.find((x) => x.tipo === "interior");
  const alerta = capital === void 0 ? "Cidade n\xE3o informada: calculado como Interior. Capital e Interior 2 t\xEAm outros pre\xE7os." : daUf.some((x) => x.tipo === "interior2") ? "Calculado como Interior 1. A lista de cidades do Interior 2 ainda n\xE3o foi carregada." : void 0;
  return { rota: interior, alerta };
}
function calcular(t, rota, req) {
  const g = t.generalidades;
  const real = pesoReal(req);
  const cubado = cubagemM3(req) * g.fator_cubagem_kg_m3;
  const peso = Math.max(real, cubado);
  const nf = req.valor_nf;
  let fretePeso;
  if (peso <= 100) {
    const i = t.faixas_kg.findIndex((lim) => peso <= lim);
    fretePeso = rota[COL_FAIXA[i]];
  } else {
    fretePeso = rota.ate100 + (peso - 100) / 1e3 * rota.excedente_ton;
  }
  const fracoes = Math.ceil(peso / g.pedagio_fracao_kg);
  const adv = Math.max(rota.adv_pct / 100 * nf, rota.adv_min);
  const gris = Math.max(rota.gris_pct / 100 * nf, rota.gris_min);
  const tso = Math.max(rota.tso_pct / 100 * nf, rota.tso_min);
  const pedagio = fracoes * rota.pedagio_100kg;
  const emex = fracoes * rota.emex;
  const taxas = rota.tas + tso + emex;
  const subtotal = fretePeso + adv + gris + pedagio + taxas;
  const aliq = g.icms_incluso ? 0 : aliquotaIcmsDeMG(rota.uf);
  const total = subtotal / (1 - aliq);
  return {
    peso_taxado_kg: arred(peso, 3),
    composicao: {
      frete_peso: arred(fretePeso),
      ad_valorem: arred(adv),
      gris: arred(gris),
      pedagio: arred(pedagio),
      taxas: arred(taxas),
      icms: arred(total - subtotal)
    },
    preco_total: arred(total),
    aliquota_icms: aliq
  };
}
function tabelaFracionadaAdapter(t, opts = {}) {
  const id = `tabela:${t.transportadora.toLowerCase()}-${t.tabela}`;
  const base = { adaptador: id, transportadora: t.transportadora, servico: "Rodovi\xE1rio", fonte: "tabela" };
  return {
    id,
    transportadora: t.transportadora,
    fonte: "tabela",
    atende(req) {
      const uf = req.destino.uf ?? ufPorCep(req.destino.cep);
      if (!uf || !t.rotas.some((r) => r.uf === uf)) return { ok: false, motivo: `sem rota para ${uf ?? "CEP desconhecido"}` };
      if (opts.limitePesoKg && pesoReal(req) > opts.limitePesoKg) return { ok: false, motivo: "acima do peso da tabela" };
      return { ok: true };
    },
    async cotar(req) {
      const uf = req.destino.uf ?? ufPorCep(req.destino.cep);
      const { rota, alerta } = escolherRota(t, uf, req.destino.cidade);
      if (!rota) return [{ ...base, status: "nao_atende", mensagem: `sem rota para ${uf}` }];
      const c = calcular(t, rota, req);
      return [{
        ...base,
        status: "ok",
        preco_total: c.preco_total,
        composicao: c.composicao,
        peso_taxado_kg: c.peso_taxado_kg,
        volumes: qtdVolumes(req),
        mensagem: [
          `Rota ${rota.percurso}`,
          `ICMS ${(c.aliquota_icms * 100).toFixed(0)}% por fora`,
          "tabela sem prazo de entrega",
          alerta
        ].filter(Boolean).join(" \xB7 "),
        raw: { rota: rota.percurso, calculo: c }
      }];
    }
  };
}

